internal fun translate(language: String, source: String): String =
    translations[source]?.get(when(language) { "ru" -> 1; "en" -> 2; else -> 0 }) ?: source

@Composable internal fun tr(source: String): String = translate(LocalUiLanguage.current, source)
@Composable internal fun currentUiLocale(): Locale = uiLocale(LocalUiLanguage.current)
